export function johtoGoldEncounterPools(
  worldOrPokeApiLocationId: string,
  method: JohtoEncounterMethod = 'walk',
  period: JohtoEncounterPeriod = 'day',
  locationAreaName?: string,
): readonly JohtoGoldEncounterPool[] {
  const locationId = JOHTO_WORLD_LOCATION_TO_POKEAPI[worldOrPokeApiLocationId as keyof typeof JOHTO_WORLD_LOCATION_TO_POKEAPI]
    ?? worldOrPokeApiLocationId;
  return JOHTO_GOLD_ENCOUNTERS.filter(pool =>
    pool.locationId === locationId && pool.method === method && pool.period === period
    && (locationAreaName === undefined || pool.locationAreaName === locationAreaName));
}
